import type { SharedV4ProviderOptions } from '@ai-sdk/provider'
import { AiProvider } from './getModel'
import models, { type ModelInfo } from './prices'

export type GetProviderOptionsArgs = {
  provider: AiProvider
  modelId: string
  parameters?: Record<string, unknown>
  supportThinking?: boolean
}

/**
 * Generates provider-specific options for enabling thinking capabilities.
 *
 * @param options The options for generating provider options.
 * @returns A provider options object for the `streamText` call.
 */
export function getProviderOptions(options: GetProviderOptionsArgs): SharedV4ProviderOptions {
  const { provider, modelId, parameters, supportThinking } = options

  if (!provider || !modelId) {
    return {}
  }

  const reasoningEffort = parameters?.reasoningEffort
  if (provider === AiProvider.OpenAICompatible && typeof reasoningEffort === 'string') {
    return {
      openaiCompatible: { reasoningEffort },
    }
  }

  const thinkingBudgetTokens = typeof parameters?.thinkingBudgetTokens === 'number' ? parameters.thinkingBudgetTokens : 0

  if (thinkingBudgetTokens <= 0) {
    return {}
  }

  const providerModels: Record<string, ModelInfo> = models[provider]
  const modelInfo = providerModels[modelId]
  const providerSupportsThinking = provider === AiProvider.OpenRouter || !!modelInfo?.supportsThinking
  const shouldSupportThinking = supportThinking ?? providerSupportsThinking

  if (!shouldSupportThinking) {
    return {}
  }

  const providerOptions: SharedV4ProviderOptions = {}

  switch (provider) {
    case AiProvider.Anthropic:
      providerOptions.anthropic = {
        thinking: { type: 'enabled', budgetTokens: thinkingBudgetTokens },
      }
      break
    case AiProvider.OpenRouter:
      providerOptions.openrouter = {
        reasoning: {
          max_tokens: thinkingBudgetTokens,
        },
      }
      break
    case AiProvider.GoogleVertex:
    case AiProvider.Google:
      providerOptions.google = {
        thinkingConfig: {
          includeThoughts: true,
          thinkingBudget: thinkingBudgetTokens,
        },
      }
      break
    case AiProvider.DeepSeek:
      break
    case AiProvider.OpenAI:
    case AiProvider.OpenAICompatible:
      break
  }

  return providerOptions
}
